// クイズ生成エンジン
class KanjiQuizEngine {
  constructor(db) {
    this.db = db;
    this.gradeMap = { 1: [], 2: [], 3: [], 4: [], 5: [], 6: [] };
    this.charMap = {};
    for (const item of this.db) {
      this.gradeMap[item.g].push(item);
      this.charMap[item.k] = item;
    }
  }

  // 現在のフロア(1〜100)から対象学年を決定
  getGradeForFloor(floor) {
    if (floor <= 15) return 1;       // 1〜15F: 1年生 (80字)
    if (floor <= 35) return 2;       // 16〜35F: 2年生 (160字)
    if (floor <= 55) return 3;       // 36〜55F: 3年生 (200字)
    if (floor <= 75) return 4;       // 56〜75F: 4年生 (202字)
    if (floor <= 90) return 5;       // 76〜90F: 5年生 (193字)
    if (floor <= 99) return 6;       // 91〜99F: 6年生 (191字)
    return Math.floor(Math.random() * 6) + 1; // 100F: 全学年総復習
  }

  // 配列をシャッフル
  shuffle(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  // 指定フロア・学年の漢字クイズを生成
  generateQuiz(floor, specificKanji = null) {
    const grade = this.getGradeForFloor(floor);
    const pool = this.gradeMap[grade];
    const target = specificKanji || pool[Math.floor(Math.random() * pool.length)];

    // 出題可能な問題タイプの候補
    const availableTypes = ['stroke'];
    if (target.kun && target.kun.length > 0) availableTypes.push('kun');
    if (target.on && target.on.length > 0) availableTypes.push('on');
    if (target.antonym && this.charMap[target.antonym]) availableTypes.push('antonym');
    if (target.kun.length > 0 || target.on.length > 0) availableTypes.push('kanji_choice');

    const qType = availableTypes[Math.floor(Math.random() * availableTypes.length)];

    switch (qType) {
      case 'kun':
        return this.createKunQuiz(target, grade, floor);
      case 'on':
        return this.createOnQuiz(target, grade, floor);
      case 'stroke':
        return this.createStrokeQuiz(target, grade, floor);
      case 'antonym':
        return this.createAntonymQuiz(target, grade, floor);
      case 'kanji_choice':
        return this.createKanjiChoiceQuiz(target, grade, floor);
      default:
        return this.createKunQuiz(target, grade, floor);
    }
  }

  // 訓読みクイズ
  createKunQuiz(target, grade, floor) {
    const correct = target.kun[0];
    const dummyPool = this.db.filter(k => k.k !== target.k && k.kun && k.kun.length > 0);
    const shuffledDummies = this.shuffle(dummyPool);
    const choices = [correct];
    for (const d of shuffledDummies) {
      const dKun = d.kun[0];
      if (dKun !== correct && !choices.includes(dKun)) {
        choices.push(dKun);
        if (choices.length === 4) break;
      }
    }
    const shuffledChoices = this.shuffle(choices);
    const correctIdx = shuffledChoices.indexOf(correct);

    const onStr = target.on.length > 0 ? target.on.join('、') : 'なし';
    const kunStr = target.kun.join('、');

    return {
      floor,
      grade,
      kanji: target.k,
      type: '訓読み（くんよみ）',
      question: `漢字【 ${target.k} 】の訓読み（くんよみ）として正しいものはどれ？`,
      detail: `【${target.k}】 訓読み: ${kunStr} / 音読み: ${onStr}（${target.s}画・小学${target.g}年）`,
      choices: shuffledChoices,
      correctIndex: correctIdx,
      target
    };
  }

  // 音読みクイズ
  createOnQuiz(target, grade, floor) {
    const correct = target.on[0];
    const dummyPool = this.db.filter(k => k.k !== target.k && k.on && k.on.length > 0);
    const shuffledDummies = this.shuffle(dummyPool);
    const choices = [correct];
    for (const d of shuffledDummies) {
      const dOn = d.on[0];
      if (dOn !== correct && !choices.includes(dOn)) {
        choices.push(dOn);
        if (choices.length === 4) break;
      }
    }
    const shuffledChoices = this.shuffle(choices);
    const correctIdx = shuffledChoices.indexOf(correct);

    const onStr = target.on.join('、');
    const kunStr = target.kun.length > 0 ? target.kun.join('、') : 'なし';

    return {
      floor,
      grade,
      kanji: target.k,
      type: '音読み（おんよみ）',
      question: `漢字【 ${target.k} 】の音読み（おんよみ）として正しいものはどれ？`,
      detail: `【${target.k}】 音読み: ${onStr} / 訓読み: ${kunStr}（${target.s}画・小学${target.g}年）`,
      choices: shuffledChoices,
      correctIndex: correctIdx,
      target
    };
  }

  // 画数クイズ
  createStrokeQuiz(target, grade, floor) {
    const correct = `${target.s} 画`;
    const offsets = [-2, -1, 1, 2, 3, -3];
    const shuffledOffsets = this.shuffle(offsets);
    const choices = [correct];
    for (const off of shuffledOffsets) {
      const cand = target.s + off;
      if (cand > 0) {
        const text = `${cand} 画`;
        if (!choices.includes(text)) {
          choices.push(text);
          if (choices.length === 4) break;
        }
      }
    }
    const shuffledChoices = this.shuffle(choices);
    const correctIdx = shuffledChoices.indexOf(correct);

    return {
      floor,
      grade,
      kanji: target.k,
      type: '画数（かくすう）',
      question: `漢字【 ${target.k} 】の総画数はぜんぶで何画？`,
      detail: `【${target.k}】 は全部で ${target.s} 画です。（小学${target.g}年で習う漢字）`,
      choices: shuffledChoices,
      correctIndex: correctIdx,
      target
    };
  }

  // 反義語（反対の意味の漢字）クイズ
  createAntonymQuiz(target, grade, floor) {
    const correct = target.antonym;
    const dummyPool = this.gradeMap[grade].filter(k => k.k !== target.k && k.k !== correct);
    const shuffledDummies = this.shuffle(dummyPool);
    const choices = [correct];
    for (const d of shuffledDummies) {
      if (!choices.includes(d.k)) {
        choices.push(d.k);
        if (choices.length === 4) break;
      }
    }
    const shuffledChoices = this.shuffle(choices);
    const correctIdx = shuffledChoices.indexOf(correct);

    return {
      floor,
      grade,
      kanji: target.k,
      type: '反対の漢字（対義語）',
      question: `漢字【 ${target.k} 】と反対の意味をもつ漢字はどれ？`,
      detail: `【${target.k}】の反対は【${correct}】です。（対義語ペア）`,
      choices: shuffledChoices,
      correctIndex: correctIdx,
      target
    };
  }

  // 読みから漢字を当てる書き取りクイズ
  createKanjiChoiceQuiz(target, grade, floor) {
    const reading = target.kun.length > 0 ? target.kun[0] : target.on[0];
    const correct = target.k;
    const dummyPool = this.gradeMap[grade].filter(k => k.k !== correct);
    const shuffledDummies = this.shuffle(dummyPool);
    const choices = [correct];
    for (const d of shuffledDummies) {
      if (!choices.includes(d.k)) {
        choices.push(d.k);
        if (choices.length === 4) break;
      }
    }
    const shuffledChoices = this.shuffle(choices);
    const correctIdx = shuffledChoices.indexOf(correct);

    const onStr = target.on.length > 0 ? target.on.join('、') : 'なし';
    const kunStr = target.kun.length > 0 ? target.kun.join('、') : 'なし';

    return {
      floor,
      grade,
      kanji: target.k,
      type: '漢字の選定（読みから漢字当て）',
      question: `読みが「 ${reading} 」である漢字はどれ？`,
      detail: `【${target.k}】 読み: ${reading}（音: ${onStr} / 訓: ${kunStr}・${target.s}画）`,
      choices: shuffledChoices,
      correctIndex: correctIdx,
      target
    };
  }
}

